const nums = [10, 5, 20, 7];
const byHalf = Object.groupBy(nums, (_, i) => (i < 2 ? "first" : "second"));
const byBig = Object.groupBy(nums, (n) => n >= 10);

console.log(byHalf.first.join(", "));
console.log(byBig.true.length, byBig.false.length);
console.log(Object.keys(byBig).join(", "));
